import json
import math
import sys

locationName = sys.argv[1].strip()
addressLine1 = sys.argv[2].strip()
addressLine2 = sys.argv[3].strip()
city = sys.argv[4].strip()
stateProvince = sys.argv[5].strip()
postalCode = sys.argv[6].strip()
country = sys.argv[7].strip().upper()
latitudeText = sys.argv[8].strip()
longitudeText = sys.argv[9].strip()

acceptedCountryCodes = set("AD,AE,AF,AG,AI,AL,AM,AO,AQ,AR,AS,AT,AU,AW,AX,AZ,BA,BB,BD,BE,BF,BG,BH,BI,BJ,BL,BM,BN,BO,BQ,BR,BS,BT,BV,BW,BZ,CA,CC,CD,CF,CG,CH,CI,CK,CL,CM,CN,CO,CR,CV,CW,CX,CY,CZ,DE,DJ,DK,DM,DO,DZ,EC,EE,EG,EH,ER,ES,ET,FI,FJ,FK,FM,FO,FR,GA,GB,GD,GE,GF,GG,GH,GI,GL,GM,GN,GP,GQ,GR,GS,GT,GU,GW,GY,HK,HM,HN,HR,HT,HU,ID,IE,IL,IM,IN,IO,IQ,IS,IT,JE,JM,JO,JP,KE,KG,KH,KI,KM,KN,KR,KW,KY,KZ,LA,LB,LC,LI,LK,LR,LS,LT,LU,LV,LY,MA,MC,MD,ME,MF,MG,MH,MK,ML,MM,MN,MO,MP,MQ,MR,MS,MT,MU,MV,MW,MX,MY,MZ,NA,NC,NE,NF,NG,NI,NL,NO,NP,NR,NU,NZ,OM,PA,PE,PF,PG,PH,PK,PL,PM,PN,PR,PS,PT,PW,PY,QA,RE,RO,RS,RW,SA,SB,SC,SD,SE,SG,SH,SI,SJ,SK,SL,SM,SN,SO,SR,SS,ST,SV,SX,SZ,TC,TD,TF,TG,TH,TJ,TK,TL,TM,TN,TO,TR,TT,TV,TW,TZ,UA,UG,UM,US,UY,UZ,VA,VC,VE,VG,VI,VN,VU,WF,WS,YE,YT,ZA,ZM,ZW".split(","))
errors = []
latitudeValue = None
longitudeValue = None

if not locationName:
    errors.append("Location Name must not be blank.")
if country and country not in acceptedCountryCodes:
    errors.append("Country must be an ISO 3166-1 alpha-2 code accepted by Cisco Intersight.")
if bool(latitudeText) != bool(longitudeText):
    errors.append("Latitude and Longitude must either both be supplied or both be empty.")
elif latitudeText and longitudeText:
    try:
        latitudeValue = float(latitudeText)
        longitudeValue = float(longitudeText)
    except ValueError:
        errors.append("Latitude and Longitude must be decimal numbers.")
    else:
        if not math.isfinite(latitudeValue) or not math.isfinite(longitudeValue):
            errors.append("Latitude and Longitude must be finite decimal numbers.")
        else:
            if latitudeValue < -90 or latitudeValue > 90:
                errors.append("Latitude must be between -90 and 90.")
            if longitudeValue < -180 or longitudeValue > 180:
                errors.append("Longitude must be between -180 and 180.")

validationStatus = "invalid" if errors else "valid"
validationError = " ".join(errors)
escapedLocationName = ""
requestBody = ""

if validationStatus == "valid":
    escapedLocationName = locationName.replace("'", "''")
    payload = {"ClassId": "asset.GeoLocation", "ObjectType": "asset.GeoLocation", "Name": locationName}
    addressFields = {"Address1": addressLine1, "Address2": addressLine2, "City": city, "StateProvince": stateProvince, "PostalCode": postalCode, "Country": country}
    populatedAddressFields = {key: value for key, value in addressFields.items() if value}
    if populatedAddressFields:
        address = {"ClassId": "comm.PhysicalAddress", "ObjectType": "comm.PhysicalAddress"}
        address.update(populatedAddressFields)
        payload["Address"] = address
    if latitudeValue is not None and longitudeValue is not None:
        payload["Coordinates"] = {"ClassId": "comm.GeoPoint", "ObjectType": "comm.GeoPoint", "Latitude": latitudeValue, "Longitude": longitudeValue}
    requestBody = json.dumps(payload, separators=(",", ":"), ensure_ascii=False, allow_nan=False)
